"use client";

import {
  type ComponentPropsWithoutRef,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useState,
} from "react";

// @interlace/flip-words v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/flip-words
// What changed since: https://ds.interlace.tools/c/flip-words#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — FlipWords
 *
 * A headline word that flips through a list. Each replacement enters
 * letter-by-letter out of an 8px blur while the outgoing one drifts up, blurs
 * and scales away.
 *
 * It runs itself on a `duration` dwell timer (3000ms by default), or you hand
 * it `index` + `onIndexChange` and drive it yourself.
 *
 * ## Provenance
 *
 * Our reimplementation of the Aceternity UI `FlipWords`. What is ours: a
 * numeric index with a controlled mode — upstream is uncontrolled-only and
 * derives its position from `words.indexOf(currentWord)`, which misbehaves the
 * moment the list contains a duplicate; `currentColor` instead of a hard-coded
 * `text-neutral-900 dark:text-neutral-100` pair; `pauseOnHover`; and the
 * reduced-motion branch below.
 *
 * ## Anatomy
 *
 *   FlipWords                        (span — data-slot="flip-words")
 *     ├─ span.sr-only aria-live=polite   (the announced text)
 *     └─ span[data-slot=flip-words-static]  (under reduce)
 *        | motion.span[data-slot=flip-words-word]
 *            └─ span per word
 *                └─ motion.span per letter
 *
 * The visible word is `aria-hidden` in BOTH branches. Everything a screen
 * reader gets comes from the polite live region, so the letter-by-letter
 * staging is never spelled out.
 *
 * ## Motion
 *
 * JS-driven — `motion/react` enter/exit variants plus a `setTimeout` cycle —
 * so the CSS reset in `styles/preflight.css` reaches none of it. It is gated
 * in JS, at both levels: `cyclingPaused` includes `reducedMotion`, so the
 * timer never fires, and the render swaps the entire `AnimatePresence` subtree
 * for a plain `<span>` carrying the active word. Under
 * `prefers-reduced-motion: reduce` you get one stable, readable word and no
 * animation object is ever constructed.
 *
 * `pauseOnHover` is documented as a no-op under reduce for the same reason:
 * there is nothing left to pause.
 *
 * ## Layout
 *
 * The outgoing word animates to `position: absolute`, so the span does not
 * reserve width for the longest entry. A list with very different word lengths
 * will reflow the line around it as it cycles.
 */

import { AnimatePresence, motion } from "motion/react";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/hooks/use-reduced-motion";

interface FlipWordsProps
  extends Omit<ComponentPropsWithoutRef<"span">, "children"> {
  /**
   * Ordered list of words (or short phrases) to cycle through. Each entry is
   * animated in word-by-word and letter-by-letter, then animated out before the
   * next entry enters.
   */
  words: string[];
  /**
   * Time in milliseconds a word stays on screen before flipping to the next
   * one. The enter/exit animation runs on top of this dwell time.
   * @default 3000
   */
  duration?: number;
  /**
   * The index of the word shown on first render when the component is
   * uncontrolled. Ignored when `index` is provided.
   * @default 0
   */
  defaultIndex?: number;
  /**
   * Controlled index of the active word. When provided, the component will not
   * advance on its own — drive it from the parent and pair with
   * `onIndexChange`.
   */
  index?: number;
  /**
   * Called with the next index whenever the active word changes, in both
   * controlled and uncontrolled modes.
   * @default undefined
   */
  onIndexChange?: (index: number, details: { word: string }) => void;
  /**
   * Pause cycling while the pointer is over the component, giving readers time
   * to finish the current word. Has no effect under reduced motion (cycling is
   * already disabled).
   * @default false
   */
  pauseOnHover?: boolean;
  /**
   * Stagger between each word in a multi-word entry, in seconds.
   * @default 0.3
   */
  wordStagger?: number;
  /**
   * Stagger between each letter within a word, in seconds.
   * @default 0.05
   */
  letterStagger?: number;
  /**
   * Stable selector hook for end-to-end tests. Required so consumers never rely
   * on a silent default; sub-parts derive `{value}-word` / `{value}-letter`.
   */
  "data-testid": string;
}

const SPRING = { type: "spring", stiffness: 100, damping: 10 } as const;

/**
 * FlipWords — an animated headline word that flips through a list, revealing
 * each replacement letter-by-letter with a soft blur-and-rise.
 *
 * Motion contract: under `prefers-reduced-motion: reduce` the component renders
 * the active word statically with no enter/exit animation and stops cycling, so
 * reduced-motion users get a stable, readable headline (WCAG 2.3.3).
 *
 * Color is inherited via `currentColor` by default — set the text color on a
 * parent (or pass a Tailwind text token through `className`) so the flipping
 * word matches its surrounding type. The component never ships a color literal.
 */
export function FlipWords({
  words,
  duration = 3000,
  defaultIndex = 0,
  index: controlledIndex,
  onIndexChange,
  pauseOnHover = false,
  wordStagger = 0.3,
  letterStagger = 0.05,
  className,
  "data-testid": testId,
  ...props
}: FlipWordsProps) {
  const reducedMotion = useReducedMotion();
  const liveRegionId = useId();

  const isControlled = controlledIndex !== undefined;
  const [uncontrolledIndex, setUncontrolledIndex] = useState(defaultIndex);
  const [hovered, setHovered] = useState(false);

  // Clamp so an out-of-range index (controlled or default) never renders
  // `undefined`. Empty `words` falls back to an empty string.
  const activeIndex =
    words.length === 0
      ? 0
      : ((isControlled ? controlledIndex : uncontrolledIndex) % words.length +
          words.length) %
        words.length;
  const currentWord = words[activeIndex] ?? "";

  const advance = useCallback(() => {
    if (words.length === 0) return;
    const next = (activeIndex + 1) % words.length;
    onIndexChange?.(next, { word: words[next] ?? "" });
    if (!isControlled) setUncontrolledIndex(next);
  }, [activeIndex, isControlled, onIndexChange, words]);

  // Cycle on a timer unless the parent controls the index, the user prefers
  // reduced motion, or the pointer is hovering with `pauseOnHover`.
  const cyclingPaused =
    isControlled || reducedMotion || (pauseOnHover && hovered);

  useEffect(() => {
    if (cyclingPaused || words.length <= 1) return;
    const timer = setTimeout(advance, duration);
    return () => clearTimeout(timer);
  }, [advance, cyclingPaused, duration, words.length, activeIndex]);

  const hoverHandlers = useMemo(
    () =>
      pauseOnHover
        ? {
            onPointerEnter: () => setHovered(true),
            onPointerLeave: () => setHovered(false),
          }
        : {},
    [pauseOnHover],
  );

  const segments = currentWord.split(" ");

  return (
    <span
      {...props}
      {...hoverHandlers}
      data-slot="flip-words"
      data-testid={testId}
      className={cn(
        "relative inline-block text-left text-current",
        className,
      )}
    >
      {/* Polite live region so screen readers announce each new word. */}
      <span id={liveRegionId} aria-live="polite" className="sr-only">
        {currentWord}
      </span>

      {reducedMotion ? (
        <span data-slot="flip-words-static" aria-hidden="true">
          {currentWord}
        </span>
      ) : (
        <AnimatePresence mode="wait">
          <motion.span
            key={`${currentWord}-${activeIndex}`}
            data-slot="flip-words-word"
            data-testid={`${testId}-word`}
            aria-hidden="true"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{
              opacity: 0,
              y: -40,
              x: 40,
              filter: "blur(8px)",
              scale: 2,
              position: "absolute",
            }}
            transition={SPRING}
            className="relative z-10 inline-block"
          >
            {segments.map((segment, segmentIndex) => (
              <span
                key={`${segment}-${segmentIndex}`}
                className="inline-block whitespace-nowrap"
              >
                {Array.from(segment).map((letter, letterIndex) => (
                  <motion.span
                    key={`${letter}-${letterIndex}`}
                    initial={{ opacity: 0, y: 10, filter: "blur(8px)" }}
                    animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
                    transition={{
                      delay:
                        segmentIndex * wordStagger +
                        letterIndex * letterStagger,
                      duration: 0.2,
                    }}
                    className="inline-block"
                  >
                    {letter}
                  </motion.span>
                ))}
                {segmentIndex < segments.length - 1 ? (
                  <span className="inline-block">&nbsp;</span>
                ) : null}
              </span>
            ))}
          </motion.span>
        </AnimatePresence>
      )}
    </span>
  );
}
